  var realFetch = window.fetch ? window.fetch.bind(window) : null;

  var DETAIL_RESOLVERS = [{"re":{},"listKey":"GET /api/customers","listField":"customers","wrap":"customer"},{"re":{},"listKey":null},{"re":{},"listKey":"GET /api/leads","listField":"leads","wrap":"lead"},{"re":{},"listKey":"GET /api/deals","listField":"deals","wrap":"deal"},{"re":{},"listKey":"GET /api/todos","listField":"todos","wrap":"todo"},{"re":{},"listKey":"GET /api/reminders","listField":"reminders","wrap":"reminder"},{"re":{},"listKey":"GET /api/plan-tasks","listField":"tasks","wrap":"task"},{"re":{},"listKey":"GET /api/memos","listField":"memos","wrap":"memo"},{"re":{},"listKey":null},{"re":{},"listKey":"GET /api/knowledge/assets","listField":"assets","wrap":"asset"},{"re":{},"listKey":"GET /api/prospect-runs","listField":"runs","wrap":"run"},{"re":{},"listKey":"GET /api/outbound-emails","listField":"emails","wrap":"email"},{"re":{},"listKey":"GET /api/trade-documents","listField":"documents","wrap":"document"}];
  var WRITE_HANDLERS = {};
  var INTEGRATION_EMPTY = {"integrations":[],"connections":[],"tools":[],"calls":[],"approvals":[],"events":[],"connectors":[],"reviews":[],"usage":{},"localRunners":[],"tasks":[],"auditEvents":[]};


  function jsonResponse(body, status) {
    return new Response(JSON.stringify(body), {
      status: status || 200,
      headers: { "Content-Type": "application/json" }
    });
  }

  function findInList(listKey, listField, id) {
    var entries = FIXTURES[listKey];
    if (!entries || !entries.length) return null;
    var body = entries[0].body;
    if (Array.isArray(body)) return body.find(function (x) { return x && x.id === id; }) || null;
    if (body && Array.isArray(body[listField])) return body[listField].find(function (x) { return x && x.id === id; }) || null;
    return null;
  }

  
  // ===== 个人试用版：localStorage 持久化数据层（可真实增删改并保存） =====
  var TRIAL_KEY = "nnnn_trial_db_v3";
  var TRIAL_COLS = DETAIL_RESOLVERS.filter(function (dr) { return dr.listKey; });
  var TRIAL_COL_PATH = {};
  TRIAL_COLS.forEach(function (dr) { TRIAL_COL_PATH[dr.listKey.replace(/^GET /, "")] = dr; });

  function trialLoad() {
    var raw = null;
    try { raw = localStorage.getItem(TRIAL_KEY); } catch (e) {}
    if (raw) {
      try { return JSON.parse(raw); } catch (e) {}
    }
    var db = {};
    TRIAL_COLS.forEach(function (dr) {
      var arr = [];
      var entries = FIXTURES[dr.listKey];
      if (entries && entries.length) {
        var b = entries[0].body;
        if (Array.isArray(b)) arr = b;
        else if (b && Array.isArray(b[dr.listField])) arr = b[dr.listField];
      }
      db[dr.listField] = arr;
      if (dr.listField === "deals" && b && Array.isArray(b.events)) db.dealEvents = b.events;
    });
    trialSave(db);
    return db;
  }
  function trialSave(db) {
    try { localStorage.setItem(TRIAL_KEY, JSON.stringify(db)); } catch (e) {}
  }
  function trialWrap(dr, item) {
    var w = {}; w[dr.wrap] = item; return w;
  }
  function trialList(method, dr, pathname, init) {
    var db = trialLoad();
    var list = db[dr.listField] || [];
    var parsed = null;
    if (init && init.body) { try { parsed = JSON.parse(init.body); } catch (e) {} }
    if (method === "GET") {
      var out = {}; out[dr.listField] = list;
      if (dr.listField === "customers") { out.mineCount = list.length; out.publicCount = 0; }
      if (dr.listField === "deals") { out.events = db.dealEvents || []; }
      return jsonResponse(out, 200);
    }
    if (method === "POST") {
      var item = parsed || {};
      if (!item.id) item.id = "t" + Date.now().toString(36) + Math.floor(Math.random() * 9999);
      if (!item.createdAt) item.createdAt = new Date().toISOString();
      list.unshift(item);
      db[dr.listField] = list;
      trialSave(db);
      return jsonResponse(trialWrap(dr, item), 200);
    }
    return null;
  }
  function trialDetail(method, dr, id, init) {
    var db = trialLoad();
    var list = db[dr.listField] || [];
    var parsed = null;
    if (init && init.body) { try { parsed = JSON.parse(init.body); } catch (e) {} }
    var idx = -1;
    for (var k = 0; k < list.length; k++) { if (list[k] && list[k].id === id) { idx = k; break; } }
    if (method === "GET") {
      if (idx >= 0) return jsonResponse(trialWrap(dr, list[idx]), 200);
      return jsonResponse({ message: "未找到", ok: false }, 200);
    }
    if (method === "PUT" || method === "PATCH") {
      if (idx < 0) return jsonResponse({ ok: false, message: "未找到" }, 404);
      list[idx] = Object.assign({}, list[idx], parsed || {});
      db[dr.listField] = list;
      trialSave(db);
      return jsonResponse(trialWrap(dr, list[idx]), 200);
    }
    if (method === "DELETE") {
      if (idx >= 0) { list.splice(idx, 1); db[dr.listField] = list; trialSave(db); }
      return jsonResponse({ ok: true }, 200);
    }
    if (method === "POST") {
      // 动作类写操作：成功但不改数据
      return jsonResponse({ ok: true }, 200);
    }
    return null;
  }
  function trialHandle(method, pathname, init) {
    // 1) 精确列表路径 → 走 localStorage（覆盖 fixtures，以反映增删改）
    if (TRIAL_COL_PATH[pathname]) {
      return trialList(method, TRIAL_COL_PATH[pathname], pathname, init);
    }
    // 2) 详情路径（列表路径 + "/" + 单段 id，且无 fixtures 精确 key 覆盖）
    var fullKey = method + " " + pathname;
    if (!(FIXTURES[fullKey] && FIXTURES[fullKey].length)) {
      for (var i = 0; i < TRIAL_COLS.length; i++) {
        var lp = TRIAL_COLS[i].listKey.replace(/^GET /, "");
        if (pathname.indexOf(lp + "/") === 0) {
          var rest = pathname.slice(lp.length + 1);
          if (rest && rest.indexOf("/") < 0) {
            return trialDetail(method, TRIAL_COLS[i], decodeURIComponent(rest), init);
          }
        }
      }
    }
    return null;
  }

function resolveDynamic(method, pathname, query) {
    // 详情类读取：从列表 fixture 中解析
    if (method === "GET") {
      for (var i = 0; i < DETAIL_RESOLVERS.length; i++) {
        var dr = DETAIL_RESOLVERS[i];
        var m = pathname.match(dr.re);
        if (m) {
          if (!dr.listKey) return jsonResponse({ message: "演示版暂无该详情数据", ok: false }, 200);
          var item = findInList(dr.listKey, dr.listField, decodeURIComponent(m[1]));
          if (item) {
            var wrapped = {};
            wrapped[dr.wrap] = item;
            return jsonResponse(wrapped, 200);
          }
          return jsonResponse({ message: "未找到", ok: false }, 200);
        }
      }
      // 集成中心未启用服务
      if (pathname.indexOf("/api/integrations/") === 0 || pathname.indexOf("/api/v1/access-audit-events") === 0) {
        return jsonResponse(INTEGRATION_EMPTY, 200);
      }
      // 未知 GET：按路径猜测返回空结构
      if (pathname.indexOf("/api/") === 0) {
        return jsonResponse([], 200);
      }
    }
    // 写操作通用成功
    if (method === "POST" || method === "PATCH" || method === "PUT" || method === "DELETE") {
      var base = method + " " + pathname;
      // 精确
      if (WRITE_HANDLERS[base]) return jsonResponse(WRITE_HANDLERS[base](), 200);
      // 前缀（带 id 的路径）
      for (var key in WRITE_HANDLERS) {
        var idx = key.indexOf("/{id}");
        if (idx >= 0) {
          var prefix = key.slice(0, idx) + "/";
          if (base.indexOf(prefix) === 0) return jsonResponse(WRITE_HANDLERS[key](), 200);
        }
      }
      return jsonResponse({ ok: true }, 200);
    }
    return null;
  }

  function handleApi(url, init) {
    var u = new URL(url, location.origin);
    var pathname = u.pathname;
    var query = u.search || "";
    var method = (init && init.method ? init.method : "GET").toUpperCase();
        var trial = trialHandle(method, pathname, init);
    if (trial) return trial;
    var key = method + " " + pathname;
    var entries = FIXTURES[key];
    if (entries && entries.length) {
      var entry = entries.find(function (e) { return e.query === query; }) || entries[0];
      return jsonResponse(entry.body, entry.status || 200);
    }
    var dynamic = resolveDynamic(method, pathname, query);
    if (dynamic) return dynamic;
    return jsonResponse({ ok: true }, 200);
  }

  window.fetch = function (input, init) {
    var url = typeof input === "string" ? input : (input && input.url) || "";
    // 站点根配置文件：GitHub Pages 子目录下绝对路径会 404，这里直接返回
    var uu = null;
    try { uu = new URL(url, location.origin); } catch (e) {}
    if (uu && (uu.pathname === "/product-config.json" || uu.pathname.indexOf("product-config.json") >= 0)) {
      return Promise.resolve(jsonResponse({ productName: "NnNn", version: "1.5.17" }, 200));
    }
    if (url.indexOf("/api/") >= 0 || url.indexOf("/whatsapp-plugin/api/") >= 0) {
      return Promise.resolve(handleApi(url, init || {}));
    }
    if (realFetch) return realFetch(input, init);
    return Promise.reject(new Error("no fetch"));
  };

